results.js:
morse.watch("div.tbl", el => {
  const sc = el.querySelector(".sc");
  if (!sc || el.querySelector(".csv-export")) return;
  const btn = morse.el("button", {
    class: "csv-export",
    text: "Export CSV",
    style: "float:right;margin:0 0 8px;font:inherit;font-size:12px;padding:4px 10px;border:1px solid rgba(23,43,77,.2);border-radius:6px;background:#fff;color:inherit;cursor:pointer",
    on: {
      click: () => {
        const rows = morse.$$("div.tbl table tr");
        const csv = rows.map(tr =>
          [...tr.children].map(c => {
            const v = c.textContent.trim();
            return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v;
          }).join(",")
        ).join("\n");
        const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
        const a = morse.el("a", { href: url, download: "orders.csv" });
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
        morse.toast("Exported " + Math.max(rows.length - 1, 0) + " orders");
      }
    }
  });
  sc.before(btn);
});

