  const sum = [...table.querySelectorAll("tbody td.am")]
    .reduce((s, td) => s + (parseFloat(td.textContent) || 0), 0);
  const text = "$" + sum.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  let foot = table.querySelector("tfoot.mn-total");
  if (!foot) {
    foot = morse.el("tfoot", { class: "mn-total" },
      morse.el("tr", {},
        morse.el("td", { text: "Total", colspan: "4" }),
        morse.el("td", { class: "am" })));
    table.appendChild(foot);
  }
  const cell = foot.querySelector("td.am");
  if (cell.textContent !== text) cell.textContent = text;
}, { live: true });

