morse.watch('div[aria-label="Formatting"]', bar => {
  if (bar.querySelector('.date-btn')) return;
  const btn = morse.el('button', {
    class: 'date-btn',
    title: "Insert today's date",
    text: 'Date',
    on: {
      click: () => {
        const d = new Date();
        const text = d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        const box = morse.$('div[role="textbox"]');
        if (!box) return;
        box.focus();
        const sel = window.getSelection();
        if (sel && sel.rangeCount && box.contains(sel.anchorNode)) {
          const range = sel.getRangeAt(0);
          range.deleteContents();
          range.insertNode(document.createTextNode(text));
          range.collapse(false);
        } else {
          box.appendChild(morse.el('p', { text }));
        }
        box.dispatchEvent(new Event('input', { bubbles: true }));
      }
    }
  });
  bar.appendChild(btn);
});

