results.js:
morse.watch("body > main > header[role='banner'] > div.h7r", (bar) => {
  const btn = morse.el("button", {
    type: "button",
    "data-morse-copy": "",
    text: "Copy as Markdown",
    on: {
      click: async () => {
        const msgs = morse.$$("section[aria-label='Conversation'] .msg");
        const md = msgs.map((m) => {
          const role = m.getAttribute("data-role") === "user" ? "**You**" : "**Parley**";
          const body = m.innerText.trim();
          return `${role}\n\n${body}`;
        }).join("\n\n---\n\n");
        try {
          await navigator.clipboard.writeText(md);
          morse.toast("Conversation copied as Markdown");
        } catch (e) {
          morse.toast("Could not copy to clipboard");
        }
      }
    }
  });
  bar.insertBefore(btn, bar.firstChild);
});

morse.watch("textarea[aria-label=\"Message Parley\"]", el => {
  if (el._escClear) return;
  const handler = e => {
    if (e.key === "Escape" && el.value !== "") {
      el.value = "";
      el.dispatchEvent(new Event("input", { bubbles: true }));
    }
  };
  el.addEventListener("keydown", handler);
  el._escClear = handler;
});

