results.js:
morse.watch('div[data-testid="player-controls"] .btns', (btns) => {
  if (btns.querySelector('.sleep-timer')) return;
  let timer = null;
  const label = morse.el('span', { class: 'sleep-label', style: 'font-size:12px;margin-left:4px;opacity:.7' });
  const btn = morse.el('button', {
    class: 'sleep-timer',
    'aria-label': 'Sleep timer',
    text: '⏾',
    on: {
      click: () => {
        if (timer) {
          clearTimeout(timer);
          timer = null;
          label.textContent = '';
          morse.toast('Sleep timer cancelled');
          return;
        }
        const mins = 15;
        timer = setTimeout(() => {
          timer = null;
          label.textContent = '';
          const pp = document.querySelector('button[data-testid="play-pause"]');
          if (pp && pp.getAttribute('aria-label') === 'Pause') pp.click();
          morse.toast('Sleep timer: playback paused');
        }, mins * 60 * 1000);
        label.textContent = mins + ' min';
        morse.toast('Sleep timer set for ' + mins + ' minutes');
      }
    }
  });
  btns.appendChild(btn);
  btns.appendChild(label);
});

morse.on(document, "keydown", e => {
  if (e.code !== "Space" || e.repeat || e.metaKey || e.ctrlKey || e.altKey) return;
  const t = e.target;
  if (t.closest && t.closest("input, textarea, select, button, a, [contenteditable='true']")) return;
  e.preventDefault();
  morse.$('button[data-testid="play-pause"]')?.click();
});
